+#!/usr/bin/env node
+import fs from "node:fs";
+import path from "node:path";
+import { parseTasks } from "./tasks.ts";
+import { planOrder } from "./planner.ts";
+import { TaskPlanError } from "./errors.ts";
+
+const USAGE = "Usage: node src/cli.ts plan <file.json> [--json]";
+
+function printUsage(): string {
+  return USAGE + "\n";
+}
+
+function isHelpArg(a: string): boolean {
+  return a === "--help" || a === "-h";
+}
+
+function main(): void {
+  const rawArgs = process.argv.slice(2);
+
+  // Handle top-level help: `node src/cli.ts --help` or `node src/cli.ts -h` or `node src/cli.ts help`
+  // and `node src/cli.ts plan --help`
+  if (rawArgs.length === 0) {
+    process.stderr.write(printUsage());
+    process.exit(2);
+  }
+
+  // If first arg is help
+  if (isHelpArg(rawArgs[0]!) || rawArgs[0] === "help") {
+    process.stdout.write(printUsage());
+    process.exit(0);
+  }
+
+  const command = rawArgs[0];
+  if (command !== "plan") {
+    process.stderr.write(printUsage());
+    process.exit(2);
+  }
+
+  // Check for help after plan: `plan --help` or `plan -h`
+  // According to acceptance, `plan --help` works
+  const afterPlan = rawArgs.slice(1);
+  if (afterPlan.length === 1 && isHelpArg(afterPlan[0]!)) {
+    process.stdout.write(printUsage());
+    process.exit(0);
+  }
+  // Also if any help flag appears, treat as help if no file? But spec says unknown option => usage error.
+  // We'll treat --help / -h anywhere after plan as help only if it's the sole arg, otherwise usage error.
+  // However to be safe, if help appears alongside other args, consider it usage/ help.
+  // Simpler: if any arg is --help/-h, show usage and exit 0 if file not present, else usage error.
+  // We'll handle: if afterPlan includes help, show usage.
+  for (const a of afterPlan) {
+    if (isHelpArg(a)) {
+      // If help is mixed with file, consider it as help request
+      process.stdout.write(printUsage());
+      process.exit(0);
+    }
+  }
+
+  // Parse options and file argument after `plan`
+  let jsonFlag = false;
+  let jsonCount = 0;
+  let fileArg: string | undefined;
+  const unknownOptions: string[] = [];
+
+  // Support --json and --format json / --format=json as json flag
+  for (let i = 0; i < afterPlan.length; i++) {
+    const arg = afterPlan[i]!;
+    if (arg === "--json") {
+      jsonCount++;
+      jsonFlag = true;
+    } else if (arg === "--format") {
+      const next = afterPlan[i + 1];
+      if (next === "json") {
+        jsonCount++;
+        jsonFlag = true;
+        i++; // consume next
+      } else {
+        // unknown format value or missing -> usage error
+        process.stderr.write(printUsage());
+        process.exit(2);
+      }
+    } else if (arg.startsWith("--format=")) {
+      const val = arg.slice("--format=".length);
+      if (val === "json") {
+        jsonCount++;
+        jsonFlag = true;
+      } else {
+        process.stderr.write(printUsage());
+        process.exit(2);
+      }
+    } else if (arg.startsWith("-")) {
+      unknownOptions.push(arg);
+    } else {
+      // positional file argument
+      if (fileArg === undefined) {
+        fileArg = arg;
+      } else {
+        // extra argument
+        process.stderr.write(printUsage());
+        process.exit(2);
+      }
+    }
+  }
+
+  if (unknownOptions.length > 0) {
+    process.stderr.write(printUsage());
+    process.exit(2);
+  }
+
+  if (jsonCount > 1) {
+    process.stderr.write(printUsage());
+    process.exit(2);
+  }
+
+  if (fileArg === undefined) {
+    process.stderr.write(printUsage());
+    process.exit(2);
+  }
+
+  // Resolve relative path against cwd
+  const filePath = path.resolve(process.cwd(), fileArg);
+
+  let content: string;
+  try {
+    content = fs.readFileSync(filePath, "utf8");
+  } catch (e: unknown) {
+    const reason = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error: ${reason}\n` + printUsage());
+    process.exit(2);
+  }
+
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(content);
+  } catch (e: unknown) {
+    const desc = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error INVALID_JSON: ${desc}\n`);
+    process.exit(1);
+  }
+
+  try {
+    const tasks = parseTasks(parsed);
+    const result = planOrder(tasks);
+
+    if (jsonFlag) {
+      const out = JSON.stringify({ order: result.order, stages: result.stages });
+      process.stdout.write(out + "\n");
+    } else {
+      let out = "";
+      if (result.stages.length === 0) {
+        out = "Order:\n";
+      } else {
+        for (let k = 0; k < result.stages.length; k++) {
+          const ids = result.stages[k]!;
+          out += `Stage ${k + 1}: ${ids.join(", ")}\n`;
+        }
+        out += `Order: ${result.order.join(", ")}\n`;
+      }
+      process.stdout.write(out);
+    }
+    process.exit(0);
+  } catch (e: unknown) {
+    if (e instanceof TaskPlanError) {
+      const code = (e as TaskPlanError).code;
+      const msg = e instanceof Error ? e.message : String(e);
+      process.stderr.write(`error ${code}: ${msg}\n`);
+      process.exit(1);
+    } else {
+      // Unexpected error - treat as library error? But spec says exit 1 with code
+      // Fallback to generic error
+      const msg = e instanceof Error ? e.message : String(e);
+      process.stderr.write(`error: ${msg}\n`);
+      process.exit(1);
+    }
+  }
+}
+
+main();
