+import { CycleError, DuplicateTaskError, UnknownDependencyError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of planning tasks: a total order and parallel stages. */
+export interface PlanResult {
+  /** Every task id in execution order respecting dependencies and priority. */
+  order: string[];
+  /** stages[k] holds tasks that can run at round k, ordered by priority. */
+  stages: string[][];
+}
+
+/**
+ * Plans execution order for tasks using Kahn's algorithm with deterministic
+ * tie-breaking. Validates duplicate ids, unknown dependencies and cycles
+ * in that order.
+ *
+ * @param tasks - tasks in the shape returned by parseTasks
+ * @returns order and stages as defined in SPEC.md R1 and R2
+ * @throws DuplicateTaskError when duplicate ids exist
+ * @throws UnknownDependencyError when a dependency is missing
+ * @throws CycleError when the graph contains a cycle
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  const n = tasks.length;
+  if (n === 0) return { order: [], stages: [] };
+
+  // R3 step 1: duplicate ids
+  const firstPos = new Map<string, number>();
+  const counts = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const id = t.id;
+    if (!firstPos.has(id)) firstPos.set(id, i);
+    counts.set(id, (counts.get(id) ?? 0) + 1);
+  }
+  const duplicates: Array<{ id: string; first: number }> = [];
+  for (const [id, c] of counts) {
+    if (c > 1) {
+      const fp = firstPos.get(id)!;
+      duplicates.push({ id, first: fp });
+    }
+  }
+  if (duplicates.length > 0) {
+    duplicates.sort((a, b) => a.first - b.first);
+    throw new DuplicateTaskError(duplicates.map((d) => d.id));
+  }
+
+  // Map id -> index for fast lookup
+  const idToIndex = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    idToIndex.set(tasks[i]!.id, i);
+  }
+
+  // R3 step 2: unknown dependency - earliest task, earliest entry
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const dependsOn = t.dependsOn ?? [];
+    const seen = new Set<string>();
+    for (const dep of dependsOn) {
+      if (seen.has(dep)) continue;
+      seen.add(dep);
+      if (!idToIndex.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  // Build deduped dependencies per task (indices)
+  const depIndices: number[][] = new Array(n);
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const raw = t.dependsOn ?? [];
+    const seen = new Set<string>();
+    const list: number[] = [];
+    for (const dep of raw) {
+      if (seen.has(dep)) continue;
+      seen.add(dep);
+      // validated above, so must exist
+      const idx = idToIndex.get(dep);
+      if (idx !== undefined) list.push(idx);
+    }
+    depIndices[i] = list;
+  }
+
+  // Build adjacency and indegree for Kahn
+  const indegree: number[] = new Array<number>(n).fill(0);
+  const adj: number[][] = Array.from({ length: n }, () => [] as number[]);
+  for (let i = 0; i < n; i++) {
+    const deps = depIndices[i]!;
+    indegree[i] = deps.length;
+    for (const d of deps) {
+      adj[d]!.push(i);
+    }
+  }
+
+  // Kahn with priority heap
+  const heap = new Heap<number>((a, b) => {
+    const pa = tasks[a]!.priority;
+    const pb = tasks[b]!.priority;
+    if (pa !== pb) return pb - pa;
+    return a - b;
+  });
+  for (let i = 0; i < n; i++) {
+    if (indegree[i]! === 0) heap.push(i);
+  }
+
+  const orderIndices: number[] = [];
+  while (heap.size() > 0) {
+    const cur = heap.pop()!;
+    orderIndices.push(cur);
+    const neighbors = adj[cur]!;
+    for (const nxt of neighbors) {
+      indegree[nxt]!--;
+      if (indegree[nxt]! === 0) heap.push(nxt);
+    }
+  }
+
+  if (orderIndices.length !== n) {
+    const cycle = findCycle(depIndices, tasks);
+    throw new CycleError(cycle);
+  }
+
+  const order = orderIndices.map((i) => tasks[i]!.id);
+
+  // R2 stages: level = 1 + max level of dependencies
+  const level: number[] = new Array<number>(n).fill(0);
+  let maxLevel = 0;
+  for (const idx of orderIndices) {
+    const deps = depIndices[idx]!;
+    if (deps.length === 0) {
+      level[idx] = 0;
+    } else {
+      let m = -1;
+      for (const d of deps) {
+        const lv = level[d]!;
+        if (lv > m) m = lv;
+      }
+      level[idx] = m + 1;
+    }
+    const lvIdx = level[idx]!;
+    if (lvIdx > maxLevel) maxLevel = lvIdx;
+  }
+
+  // group by level
+  const stageIndices: number[][] = Array.from({ length: maxLevel + 1 }, () => [] as number[]);
+  for (let i = 0; i < n; i++) {
+    const lv = level[i]!;
+    stageIndices[lv]!.push(i);
+  }
+  const stages: string[][] = [];
+  for (let k = 0; k <= maxLevel; k++) {
+    const arr = stageIndices[k]!;
+    arr.sort((a, b) => {
+      const pa = tasks[a]!.priority;
+      const pb = tasks[b]!.priority;
+      if (pa !== pb) return pb - pa;
+      return a - b;
+    });
+    stages.push(arr.map((i) => tasks[i]!.id));
+  }
+
+  return { order, stages };
+}
+
+/** Find a simple cycle path in the dependency graph. */
+function findCycle(depIndices: number[][], tasks: TaskSpec[]): string[] {
+  const n = depIndices.length;
+  const color = new Uint8Array(n); // 0 unvisited,1 visiting,2 done
+  const parent: number[] = new Array<number>(n).fill(-1);
+  type Frame = { v: number; next: number };
+  const stack: Frame[] = [];
+  for (let start = 0; start < n; start++) {
+    if (color[start]! !== 0) continue;
+    color[start] = 1;
+    stack.push({ v: start, next: 0 });
+    while (stack.length > 0) {
+      const frame = stack[stack.length - 1]!;
+      const v = frame.v;
+      const deps = depIndices[v]!;
+      if (frame.next < deps.length) {
+        const w = deps[frame.next++]!;
+        if (color[w]! === 0) {
+          parent[w] = v;
+          color[w] = 1;
+          stack.push({ v: w, next: 0 });
+        } else if (color[w]! === 1) {
+          // found cycle v -> w where w is ancestor
+          const rev: number[] = [];
+          let cur: number = v;
+          rev.push(cur);
+          while (cur !== w) {
+            cur = parent[cur]!;
+            rev.push(cur);
+          }
+          rev.reverse();
+          rev.push(w);
+          return rev.map((i) => tasks[i]!.id);
+        }
+      } else {
+        color[v] = 2;
+        stack.pop();
+      }
+    }
+  }
+  return [];
+}
+
+/** Simple binary heap. */
+class Heap<T> {
+  private data: T[] = [];
+  private compare: (a: T, b: T) => number;
+  constructor(compare: (a: T, b: T) => number) {
+    this.compare = compare;
+  }
+  size(): number {
+    return this.data.length;
+  }
+  push(item: T): void {
+    this.data.push(item);
+    this.bubbleUp(this.data.length - 1);
+  }
+  pop(): T | undefined {
+    if (this.data.length === 0) return undefined;
+    const top = this.data[0]!;
+    const last = this.data.pop()!;
+    if (this.data.length > 0) {
+      this.data[0] = last;
+      this.bubbleDown(0);
+    }
+    return top;
+  }
+  private bubbleUp(i: number): void {
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      if (this.compare(this.data[i]!, this.data[p]!) < 0) {
+        const tmp = this.data[i]!;
+        this.data[i] = this.data[p]!;
+        this.data[p] = tmp;
+        i = p;
+      } else break;
+    }
+  }
+  private bubbleDown(i: number): void {
+    const n = this.data.length;
+    while (true) {
+      let smallest = i;
+      const l = i * 2 + 1;
+      const r = l + 1;
+      if (l < n && this.compare(this.data[l]!, this.data[smallest]!) < 0) smallest = l;
+      if (r < n && this.compare(this.data[r]!, this.data[smallest]!) < 0) smallest = r;
+      if (smallest !== i) {
+        const tmp = this.data[i]!;
+        this.data[i] = this.data[smallest]!;
+        this.data[smallest] = tmp;
+        i = smallest;
+      } else break;
+    }
+  }
+}
