+  test("has an Unreleased entry mentioning planOrder", () => {
+    const unreleased = /^## Unreleased\n([\s\S]*?)(?=^## |$(?![\s\S]))/m.exec(read("CHANGELOG.md"))?.[1] ?? "";
+    assert.match(unreleased, /planOrder/);
+  });
+});
